pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testRegression_property() public {
        c.SetMinSum(10);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();
        address alice = address(0x123);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        bool ok;
        try c.Deposit{value: 0}() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val,string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
